namespace huffman
{
    void read_huffman_dictionary(std::ifstream &infile, std::shared_ptr<Node> &root)
    {
        unsigned char marker;
        infile.read(reinterpret_cast<char*>(&marker), sizeof(marker));

        if (marker == 0x00) // Assuming 0x00 is the null marker
        {
            root = nullptr;
            return;
        }

        // Create a new node with the read character
        root = std::make_shared<Node>(marker, 0); // Frequency is irrelevant during deserialization

        // Recursively read left and right subtrees
        read_huffman_dictionary(infile, root->left);
        read_huffman_dictionary(infile, root->right);
    }
}

